# customer's ticket history) since query_customer_db returns JSON, not a
# tabular export, and has no filter-by-field semantics to break.
_QUERY_CUSTOMER_DB_FIELDS = _CUSTOMER_QUERYABLE_FIELDS + ("ticket_ids",)


